#!/usr/bin/env bash
set -u

task=""
output_dir="outputs"
previous=""
for argument in "$@"; do
    if [[ "$previous" == "--experiment_name" ]]; then
        task="$argument"
    elif [[ "$previous" == "--output_dir" ]]; then
        output_dir="$argument"
    fi
    previous="$argument"
done

if [[ "$task" == "${FAKE_FAIL_TASK:-}" ]]; then
    echo "synthetic failure for $task" >&2
    exit 9
fi

if [[ "$task" == source_* ]]; then
    mkdir -p "$output_dir/$task/fold_0"
    : > "$output_dir/$task/fold_0/model.pt"
    printf '%s\n' \
        "========================================================================" \
        "[SOURCE] Epoch 1/1" \
        "------------------------------------------------------------------------" \
        "train:" \
        "  loss: 0.842731" \
        "ReIMTS patches:" \
        "  empty patch rate: 0.07%" \
        "timing:" \
        "  elapsed: 00:00:01" \
        "========================================================================"
else
    printf '%s\n' \
        "========================================================================" \
        "[SHIFT ESTIMATION]" \
        "------------------------------------------------------------------------" \
        "candidate_count: 121" \
        "top5:" \
        "  1. shift=0 score=0.100000" \
        "========================================================================" \
        "========================================================================" \
        "[TIMEMATCH] Epoch 1/1" \
        "------------------------------------------------------------------------" \
        "pseudo labels:" \
        "  acceptance_rate: 25.00%" \
        "timing:" \
        "  elapsed: 00:00:01" \
        "========================================================================"
fi

printf '%s\n' \
    "========================================================================" \
    "[RUN COMPLETE]" \
    "------------------------------------------------------------------------" \
    "experiment: $task" \
    "total_runtime: 00:00:01" \
    "========================================================================"
